import{_ as l,c as o,a2 as p,o as i}from"./chunks/framework.CqbvlPrP.js";const d=JSON.parse('{"title":"第一千二百零五章 最上品 不可能事经 增支部1集188经到277经","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/1205第一千二百零五章 最上品 不可能事经 增支部1集188经到277经.md","filePath":"meditation/巴利文大藏经/1205第一千二百零五章 最上品 不可能事经 增支部1集188经到277经.md"}'),u={name:"meditation/巴利文大藏经/1205第一千二百零五章 最上品 不可能事经 增支部1集188经到277经.md"};function q(a,t,r,s,e,_){return i(),o("div",null,t[0]||(t[0]=[p('<h1 id="第一千二百零五章-最上品-不可能事经-增支部1集188经到277经" tabindex="-1">第一千二百零五章 最上品 不可能事经 增支部1集188经到277经 <a class="header-anchor" href="#第一千二百零五章-最上品-不可能事经-增支部1集188经到277经" aria-label="Permalink to &quot;第一千二百零五章 最上品 不可能事经 增支部1集188经到277经&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>增支部1集188经到277经</p><p>最上品</p><ol><li>第一品</li></ol><p>188-197经</p><ol start="188"><li><p>&quot;比丘们,在我的声闻弟子中,在夜间修行方面,阿若憍陈如是最上的。&quot;</p></li><li><p>&quot;在大智慧方面,舍利弗是最上的。&quot;</p></li><li><p>&quot;在神通方面,大目犍连是最上的。&quot;</p></li><li><p>&quot;在头陀行方面,大迦叶是最上的。&quot;</p></li><li><p>&quot;在天眼方面,阿那律是最上的。&quot;</p></li><li><p>&quot;在高贵家族出身方面,跋提耶·迦梨瞿提子是最上的。&quot;</p></li><li><p>&quot;在悦耳动听的声音方面,小跋提耶是最上的。&quot;</p></li><li><p>&quot;在狮子吼方面,宾头卢·婆罗堕阇是最上的。&quot;</p></li><li><p>&quot;在说法方面,富楼那·弥多罗尼子是最上的。&quot;</p></li><li><p>&quot;在简略说法后详细解释其意义方面,摩诃迦旃延是最上的。&quot;</p></li></ol><p>第一品结束。</p><ol start="2"><li>第二品</li></ol><p>198-208经</p><ol start="198"><li><p>&quot;比丘们,在我的声闻弟子中,在以意念创造身体方面,周利槃陀伽是最上的。&quot;</p></li><li><p>&quot;在心的转变方面,周利槃陀伽是最上的。&quot;</p></li><li><p>&quot;在想的转变方面,摩诃槃陀伽是最上的。&quot;</p></li><li><p>&quot;在无诤住方面,须菩提是最上的。&quot;</p></li><li><p>&quot;在应受供养方面,须菩提是最上的。&quot;</p></li><li><p>&quot;在林居方面,离婆多·伽提罗林是最上的。&quot;</p></li><li><p>&quot;在禅修方面,疑惑离婆多是最上的。&quot;</p></li><li><p>&quot;在精进方面,苏那·拘利维沙是最上的。&quot;</p></li><li><p>&quot;在善巧言语方面,苏那·库提干那是最上的。&quot;</p></li><li><p>&quot;在获得供养方面,尸婆利是最上的。&quot;</p></li><li><p>&quot;在信解方面,婆醯利是最上的。&quot;</p></li></ol><p>第二品结束。</p><ol start="3"><li>第三品</li></ol><p>209-218经</p><ol start="209"><li><p>&quot;比丘们,在我的声闻弟子中,在喜好学习方面,罗睺罗是最上的。&quot;</p></li><li><p>&quot;在以信心出家方面,罗吒波罗是最上的。&quot;</p></li><li><p>&quot;在最先接受分配方面,军荼陀那是最上的。&quot;</p></li><li><p>&quot;在机智方面,婆耆舍是最上的。&quot;</p></li><li><p>&quot;在令人欢喜方面,优波斯那·婆耆子是最上的。&quot;</p></li><li><p>&quot;在分配住处方面,陀婆·摩罗子是最上的。&quot;</p></li><li><p>&quot;在受天神喜爱方面,毗邻陀婆蹉是最上的。&quot;</p></li><li><p>&quot;在迅速证悟方面,跋醯耶·达卢奇利耶是最上的。&quot;</p></li><li><p>&quot;在善说妙法方面,童子迦叶是最上的。&quot;</p></li><li><p>&quot;在获得无碍解方面,摩诃俱絺罗是最上的。&quot;</p></li></ol><p>第三品结束。</p><ol start="4"><li>第四品</li></ol><p>219-234经</p><ol start="219"><li><p>&quot;比丘们,在我的声闻弟子中,在多闻方面,阿难是最上的。&quot;</p></li><li><p>&quot;在具念方面,阿难是最上的。&quot;</p></li><li><p>&quot;在行为方面,阿难是最上的。&quot;</p></li><li><p>&quot;在坚毅方面,阿难是最上的。&quot;</p></li><li><p>&quot;在侍奉方面,阿难是最上的。&quot;</p></li><li><p>&quot;在大众方面,优楼频螺迦叶是最上的。&quot;</p></li><li><p>&quot;在使家族生信方面,迦留陀夷是最上的。&quot;</p></li><li><p>&quot;在少病方面,薄拘罗是最上的。&quot;</p></li><li><p>&quot;在忆念前世方面,索比多是最上的。&quot;</p></li><li><p>&quot;在持律方面,优波离是最上的。&quot;</p></li><li><p>&quot;在教导比丘尼方面,难陀迦是最上的。&quot;</p></li><li><p>&quot;在守护诸根方面,难陀是最上的。&quot;</p></li><li><p>&quot;在教导比丘方面,摩诃劫宾那是最上的。&quot;</p></li><li><p>&quot;在火界定方面,娑竭陀是最上的。&quot;</p></li><li><p>&quot;在应机说法方面,罗陀是最上的。&quot;</p></li><li><p>&quot;在粗衣着方面,摩伽罗阇是最上的。&quot;</p></li></ol><p>第四品结束。</p><ol start="5"><li>第五品</li></ol><p>235-247经</p><ol start="235"><li><p>&quot;比丘们,在我的比丘尼声闻弟子中,在夜间修行方面,摩诃波阇波提·瞿昙弥是最上的。&quot;</p></li><li><p>&quot;在大智慧方面,差摩是最上的。&quot;</p></li><li><p>&quot;在神通方面,莲华色是最上的。&quot;</p></li><li><p>&quot;在持律方面,波吒遮罗是最上的。&quot;</p></li><li><p>&quot;在说法方面,法授是最上的。&quot;</p></li><li><p>&quot;在禅修方面,难陀是最上的。&quot;</p></li><li><p>&quot;在精进方面,苏那是最上的。&quot;</p></li><li><p>&quot;在天眼方面,婆俱罗是最上的。&quot;</p></li><li><p>&quot;在迅速证悟方面,跋陀·军荼罗计娑是最上的。&quot;</p></li><li><p>&quot;在忆念前世方面,跋陀·迦毗罗是最上的。&quot;</p></li><li><p>&quot;在获得大神通方面,跋陀·迦旃延是最上的。&quot;</p></li><li><p>&quot;在粗衣着方面,吉舍瞿昙弥是最上的。&quot;</p></li><li><p>&quot;在信解方面,尸伽罗摩多是最上的。&quot;</p></li></ol><p>第五品结束。</p><p>248-257经</p><ol start="6"><li><p>第六品</p></li><li><p>&quot;比丘们,在我的优婆塞声闻弟子中,在最先皈依方面,商人塔普沙和跋利迦是最上的。&quot;</p></li><li><p>&quot;在布施方面,给孤独长者须达多是最上的。&quot;</p></li><li><p>&quot;在说法方面,摩诃迦散提迦城的质多长者是最上的。&quot;</p></li><li><p>&quot;在以四摄事摄受众人方面,阿罗毗的诃达迦是最上的。&quot;</p></li><li><p>&quot;在布施精妙食物方面,释迦族的摩诃男是最上的。&quot;</p></li><li><p>&quot;在布施可意之物方面,毗舍离的郁伽长者是最上的。&quot;</p></li><li><p>&quot;在护持僧团方面,象村的郁伽多长者是最上的。&quot;</p></li><li><p>&quot;在不动信方面,须兰跋陀是最上的。&quot;</p></li><li><p>&quot;在对个人生信方面,耆婆·拘摩罗跋蹉是最上的。&quot;</p></li><li><p>&quot;在亲密方面,那拘罗父长者是最上的。&quot;</p></li></ol><p>第六品结束。</p><ol start="7"><li>第七品</li></ol><p>258-267经</p><ol start="258"><li><p>&quot;比丘们,在我的优婆夷声闻弟子中,在最先皈依方面,军将之女须阇多是最上的。&quot;</p></li><li><p>&quot;在布施方面,毗舍佉·弥迦罗母是最上的。&quot;</p></li><li><p>&quot;在多闻方面,久寿多罗是最上的。&quot;</p></li><li><p>&quot;在慈心住方面,舍摩婆提是最上的。&quot;</p></li><li><p>&quot;在禅修方面,郁多罗难陀母是最上的。&quot;</p></li><li><p>&quot;在布施精妙食物方面,拘利族的须波婆娑是最上的。&quot;</p></li><li><p>&quot;在看护病人方面,优婆夷须毗耶是最上的。&quot;</p></li><li><p>&quot;在不动信方面,迦丁耶尼是最上的。&quot;</p></li><li><p>&quot;在亲密方面,那拘罗母长者妻是最上的。&quot;</p></li><li><p>&quot;在传闻而生信方面,家族女迦利优婆夷是最上的。&quot;</p></li></ol><p>第七品结束。</p><p>最上品第十四品结束。</p><p>不可能事经</p><ol><li>第一品</li></ol><p>268经</p><ol start="268"><li>&quot;比丘们,具足正见的人不可能认为任何有为法是常的,这是不可能的。但是,凡夫有可能认为任何有为法是常的,这是可能的。&quot;</li></ol><p>269经</p><ol start="269"><li>&quot;比丘们,具足正见的人不可能认为任何有为法是乐的,这是不可能的。但是,凡夫有可能认为任何有为法是乐的,这是可能的。&quot;</li></ol><p>270经</p><ol start="270"><li>&quot;比丘们,具足正见的人不可能认为任何法是我的,这是不可能的。但是,凡夫有可能认为任何法是我的,这是可能的。&quot;</li></ol><p>271经</p><ol start="271"><li>&quot;比丘们,具足正见的人不可能杀害自己的母亲,这是不可能的。但是,凡夫有可能杀害自己的母亲,这是可能的。&quot;</li></ol><p>272经</p><ol start="272"><li>&quot;比丘们,具足正见的人不可能杀害自己的父亲,这是不可能的。但是,凡夫有可能杀害自己的父亲,这是可能的。&quot;</li></ol><p>273经</p><ol start="273"><li>&quot;比丘们,具足正见的人不可能杀害阿罗汉,这是不可能的。但是,凡夫有可能杀害阿罗汉,这是可能的。&quot;</li></ol><p>274经</p><ol start="274"><li>&quot;比丘们,具足正见的人不可能恶意使如来流血,这是不可能的。但是,凡夫有可能恶意使如来流血,这是可能的。&quot;</li></ol><p>275经</p><ol start="275"><li>&quot;比丘们,具足正见的人不可能破和合僧,这是不可能的。但是,凡夫有可能破和合僧,这是可能的。&quot;</li></ol><p>276经</p><ol start="276"><li>&quot;比丘们,具足正见的人不可能宣称别的导师,这是不可能的。但是,凡夫有可能宣称别的导师,这是可能的。&quot;</li></ol><p>277经</p><ol start="277"><li>&quot;比丘们,在一个世界中不可能同时有两位阿罗汉、正等正觉者出现,这是不可能的。但是,在一个世界中可能有一位阿罗汉、正等正觉者出现,这是可能的。&quot;</li></ol><p>第一品结束。</p>',55)]))}const c=l(u,[["render",q]]);export{d as __pageData,c as default};
